  Home,
  FolderGit2,
  User,
  FileText,
  Mail,
  Briefcase,
  ArrowUpRight,
  TerminalSquare,
  LayoutGrid,
  Gamepad2,
  MessagesSquare,
  Copy,
  Download,
  Plug,
